// Station 1.3: Die Taxizentrale führt eine Liste der Taxis im Dienst.
// Taxis kommen dazu und melden sich wieder ab – in beliebiger Reihenfolge.

Liste imDienst = new Liste();
imDienst.add(new Taxi(12, "Stefan"));
imDienst.add(new Taxi(7, "Aylin"));
imDienst.add(new Taxi(3, "Jonas"));
imDienst.add(new Taxi(21, "Mira"));

println("Im Dienst:");
imDienst.ausgeben();
println("Anzahl: " + imDienst.laenge());

// Gleich oder dasselbe? Hier wird ein NEUES Taxi-Objekt mit gleichem Inhalt gesucht.
println("Ist Taxi 7 im Dienst? " + imDienst.enthaelt(new Taxi(7, "Aylin")));

println("Taxi 7 meldet sich ab.");
imDienst.entfernen(new Taxi(7, "Aylin"));
imDienst.ausgeben();
println("Anzahl: " + imDienst.laenge());

/**
 * Eine Liste kennt nur ihren ersten Knoten (anfang).
 * Alles Weitere erledigen die Knoten rekursiv.
 */
public class Liste {
   private Knoten anfang;

   public Liste() {
      anfang = null;
   }

   public boolean isEmpty() {
      return anfang == null;
   }

   public void ausgeben() {
      if (anfang != null) {
         anfang.ausgeben();
      }
   }

   public int laenge() {
      if (anfang == null) {
         return 0;
      } else {
         return anfang.laenge();
      }
   }

   public boolean add(DatenElement d) {
      if (anfang == null) {                 // Sonderfall: leere Liste
         anfang = new Knoten(d);
         return true;
      } else {
         return anfang.add(d);
      }
   }

   public boolean enthaelt(DatenElement d) {
      if (anfang == null) {
         return false;
      } else {
         return anfang.enthaelt(d);
      }
   }

   public boolean entfernen(DatenElement d) {
      if (anfang == null) {
         return false;
      } else if (anfang.getDaten().istGleich(d)) {   // Sonderfall: der erste Knoten
         anfang = anfang.getNachfolger();
         return true;
      } else {
         return anfang.entfernen(d);
      }
   }

   // Hilfsmethode für die Tests: alle Schlüsselwerte, durch Komma getrennt.
   public String alsText() {
      if (anfang == null) {
         return "";
      } else {
         return anfang.alsText();
      }
   }
}

/**
 * Ein Knoten der Liste: kennt seine Daten und seinen Nachfolger.
 * Die Methoden arbeiten rekursiv: Jeder Knoten erledigt seinen Teil
 * und gibt den Rest des Auftrags an seinen Nachfolger weiter.
 */
public class Knoten {
   private DatenElement daten;
   private Knoten nachfolger;

   public Knoten(DatenElement daten) {
      this.daten = daten;
      nachfolger = null;
   }

   public DatenElement getDaten() {
      return daten;
   }

   public Knoten getNachfolger() {
      return nachfolger;
   }

   public void setNachfolger(Knoten nachfolger) {
      this.nachfolger = nachfolger;
   }

   // Beispiel: gibt diesen Knoten und alle folgenden aus.
   public void ausgeben() {
      println("  " + daten.gibSchluesselwert());   // eigener Teil
      if (nachfolger != null) {                     // Abbruchbedingung
         nachfolger.ausgeben();                     // rekursiver Aufruf: der Rest
      }
   }

   // Anzahl der Knoten ab hier (diesen mitgezählt).
   public int laenge() {
      if (nachfolger == null) {             // Abbruch: letzter Knoten
         return 1;
      } else {
         return nachfolger.laenge() + 1;    // Rekursion: Rest zählen, mich dazu
      }
   }

   // Hängt einen neuen Knoten mit d ans Ende an.
   public boolean add(DatenElement d) {
      if (nachfolger == null) {             // Abbruch: am Ende angekommen
         nachfolger = new Knoten(d);
         return true;
      } else {
         return nachfolger.add(d);          // Rekursion: Auftrag weitergeben
      }
   }

   // Ist d ab hier (diesen Knoten mitgerechnet) enthalten?
   public boolean enthaelt(DatenElement d) {
      if (daten.istGleich(d)) {             // Abbruch 1: gefunden
         return true;
      } else if (nachfolger == null) {      // Abbruch 2: Ende erreicht
         return false;
      } else {
         return nachfolger.enthaelt(d);     // Rekursion
      }
   }

   // Entfernt den ersten Knoten HINTER diesem, dessen Daten gleich d sind.
   public boolean entfernen(DatenElement d) {
      if (nachfolger == null) {                       // Abbruch: nichts gefunden
         return false;
      } else if (nachfolger.getDaten().istGleich(d)) { // Vorausschau: Nachfolger prüfen
         nachfolger = nachfolger.getNachfolger();      // Nachfolger aushängen
         return true;
      } else {
         return nachfolger.entfernen(d);               // Rekursion
      }
   }

   // Hilfsmethode für die Tests: alle Schlüsselwerte ab hier, durch Komma getrennt.
   public String alsText() {
      if (nachfolger == null) {
         return daten.gibSchluesselwert();
      } else {
         return daten.gibSchluesselwert() + ", " + nachfolger.alsText();
      }
   }
}

/**
 * Der Vertrag für alles, was in einer Liste oder Warteschlange stehen darf.
 */
public interface DatenElement {
   String gibSchluesselwert();

   boolean istGleich(DatenElement d);   // inhaltlich gleich (nicht: dasselbe Objekt)
}

/**
 * Ein Taxi der Taxizentrale.
 */
public class Taxi implements DatenElement {
   private int nummer;
   private String fahrer;

   public Taxi(int nummer, String fahrer) {
      this.nummer = nummer;
      this.fahrer = fahrer;
   }

   public int getNummer() {
      return nummer;
   }

   public String getFahrer() {
      return fahrer;
   }

   public String gibSchluesselwert() {
      return "Taxi " + nummer;
   }

   public boolean istGleich(DatenElement d) {
      return gibSchluesselwert().equals(d.gibSchluesselwert());
   }
}

/**
 * Selbsttest der Taxizentrale. Bitte nicht verändern!
 * Starten: Klick auf das kleine Dreieck links neben "@Test"
 * (ganz oben: alle Tests) oder auf der Website "Tests starten".
 */
public class ListeTest {

   private Knoten kette() {
      // k1 (Taxi 12) -> k2 (Taxi 7) -> k3 (Taxi 3), ohne Liste und ohne add gebaut
      Knoten k1 = new Knoten(new Taxi(12, "Stefan"));
      Knoten k2 = new Knoten(new Taxi(7, "Aylin"));
      Knoten k3 = new Knoten(new Taxi(3, "Jonas"));
      k1.setNachfolger(k2);
      k2.setNachfolger(k3);
      return k1;
   }

   private Liste dreiTaxis() {
      Liste l = new Liste();
      l.add(new Taxi(12, "Stefan"));
      l.add(new Taxi(7, "Aylin"));
      l.add(new Taxi(3, "Jonas"));
      return l;
   }

   @Test
   public void laengeKnotenkette() {
      Assertions.assertEquals(3, kette().laenge(), "Knoten.laenge(): Eine Kette aus drei Knoten muss 3 liefern.");
   }

   @Test
   public void laengeLetzterKnoten() {
      Assertions.assertEquals(1, new Knoten(new Taxi(1, "A")).laenge(), "Knoten.laenge(): Ein einzelner Knoten muss 1 liefern.");
   }

   @Test
   public void laengeLeereListe() {
      Assertions.assertEquals(0, new Liste().laenge(), "Liste.laenge(): Eine leere Liste muss 0 liefern.");
   }

   @Test
   public void addInLeereListe() {
      Liste l = new Liste();
      Assertions.assertTrue(l.add(new Taxi(12, "Stefan")), "Liste.add() muss true zurückgeben.");
      Assertions.assertEquals("Taxi 12", l.alsText(), "Nach einem add() muss genau Taxi 12 in der Liste stehen.");
   }

   @Test
   public void addHaengtHintenAn() {
      Assertions.assertEquals("Taxi 12, Taxi 7, Taxi 3", dreiTaxis().alsText(), "add() muss hinten anhängen.");
   }

   @Test
   public void laengeNachAdd() {
      Assertions.assertEquals(3, dreiTaxis().laenge(), "Liste.laenge() nach drei add()-Aufrufen muss 3 sein.");
   }

   @Test
   public void enthaeltGleichesTaxi() {
      Assertions.assertTrue(dreiTaxis().enthaelt(new Taxi(7, "Aylin")), "enthaelt(): Ein neues, aber gleiches Taxi 7 muss gefunden werden.");
   }

   @Test
   public void enthaeltNichtVorhanden() {
      Assertions.assertFalse(dreiTaxis().enthaelt(new Taxi(99, "Zoe")), "enthaelt(): Taxi 99 ist nicht in der Liste.");
   }

   @Test
   public void enthaeltLeereListe() {
      Assertions.assertFalse(new Liste().enthaelt(new Taxi(7, "Aylin")), "enthaelt(): In einer leeren Liste ist nichts enthalten.");
   }

   @Test
   public void entfernenMitte() {
      Liste l = dreiTaxis();
      Assertions.assertTrue(l.entfernen(new Taxi(7, "Aylin")), "entfernen() muss true liefern, wenn Taxi 7 gefunden wurde.");
      Assertions.assertEquals("Taxi 12, Taxi 3", l.alsText(), "Nach entfernen(Taxi 7) bleiben Taxi 12 und Taxi 3.");
   }

   @Test
   public void entfernenErstes() {
      Liste l = dreiTaxis();
      l.entfernen(new Taxi(12, "Stefan"));
      Assertions.assertEquals("Taxi 7, Taxi 3", l.alsText(), "Das erste Taxi muss sich auch abmelden können.");
   }

   @Test
   public void entfernenLetztes() {
      Liste l = dreiTaxis();
      l.entfernen(new Taxi(3, "Jonas"));
      Assertions.assertEquals("Taxi 12, Taxi 7", l.alsText(), "Das letzte Taxi muss sich auch abmelden können.");
   }

   @Test
   public void entfernenNichtVorhanden() {
      Liste l = dreiTaxis();
      Assertions.assertFalse(l.entfernen(new Taxi(99, "Zoe")), "entfernen() muss false liefern, wenn nichts gefunden wird.");
      Assertions.assertEquals("Taxi 12, Taxi 7, Taxi 3", l.alsText(), "Die Liste darf sich dann nicht verändern.");
   }
}
